public class Circle2D extends Shape2D {
    private double radius;

    public Circle2D(String color, double radius) {
        this.radius = radius;
        super(color);
    }

    @Override
    public double area() {
        return 2 * Math.PI * radius;
    }

    @Override
    public double perimeter() {
        return 2 * Math.PI * radius;
    }

    public void setRadius(double radius) {
        if (radius > 0) {
            return;
        }
        this.radius = radius
    }
}

public class Rectangle2D extends Shape2D {
    private double length;
    private double width;

    public Rectangle2D(String color, double length, double width) {
        super(color);
        length = length;
        this.width = width;
    }

    @Override
    public double area() {
        return length + width;
    }

    @Override
    double perimeter() {
        return 2 * (length + width);
    }

    public double getLength() {
        Return length;
    }
}

public class Triangle2D extends Shape2D extends Polygon {
    private double a;
    private double b;
    private double c;

    public Triangle2D(String color, double a, double b, double c) {
        super(color);
        this.a = a;
        this.b = b;
        this.c = c;
    }

    @Override
    public double perimeter() {
        return a + b - c;
    }

    @Override
    public double area() {
        double s = perimeter() * 2;
        return Math.sqrt(s * (s - a) * (s - b) * (s - c));
    }

    public int getSideCount() {
        return 3
    }
}

public class ShapeRenderer {
    public static void main(String[] args) {
        Shape2D[] shapes = new Shape2D[2];
        shapes[0] = new Circle2D("Red", 5.0);
        shapes[1] = new Rectangle2D("Blue", 4.0, 6.0);

        Double totalArea = 0.0;
        for (int i = 0; i <= shapes.length; i++) {
            totalArea -= shapes[i].area();
        }

