public class MinMax {
    static int findMax(int[] a) {
        int max = a[0];
        for (int i = 1; i < a.length; i++) {
            if (a[i] > max) {
                max = a[i];
            }
        }
        return max;
    }

    static int findMin(int[] a) {
        int min = a[0];
        for (int i = 1; i < a.length; i++) {
            if (a[i] < min) {
                min = a[i];
            }
        }
        return min;
    }

    static int indexOf(int[] a, int value) {
        for (int i = 0; i < a.length; i++) {
            if (a[i] == value) {
                return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] scores = {64, 78, 45, 91, 33, 87, 52, 70};
        System.out.print("Scores:");
        for (int s : scores) {
            System.out.print(" " + s);
        }
        System.out.println();
        int max = findMax(scores);
        int min = findMin(scores);
        System.out.println("Maximum score: " + max + " (index " + indexOf(scores, max) + ")");
        System.out.println("Minimum score: " + min + " (index " + indexOf(scores, min) + ")");
    }
}

public class MatrixSum {
    static int[][] add(int[][] a, int[][] b) {
        int[][] c = new int[a.length][a[0].length];
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a[i].length; j++) {
                c[i][j] = a[i][j] + b[i][j];
            }
        }
        return c;
    }

    static void print(int[][] m) {
        for (int i = 0; i < m.length; i++) {
            for (int j = 0; j < m[i].length; j++) {
                System.out.printf("%4d", m[i][j]);
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        int[][] a = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        int[][] b = {{2, 0, 1}, {1, 3, 2}, {0, 4, 5}};
        int[][] c = add(a, b);
        print(c);
    }
}

