            }
        }
        return -1;
    }

    static int countOccurrences(int[] a, int target) {
        int count = 0;
        for (int i = 0; i < a.length; i++) {
            if (a[i] == target) {
                count++;
            }
        }
        return count;
    }

    static boolean contains(int[] a, int target) {
        return indexOf(a, target) != -1;
    }

